import { ToolDescriptor, TaskGenerator, DeliverableIntegrator } from "./tools/tools.js";

// Define the tools and their instances
const toolDescriptor = new ToolDescriptor();
const taskGenerator = new TaskGenerator();
const deliverableIntegrator = new DeliverableIntegrator();

// Runtime interface
export async function describeTool(toolInput: string): Promise<void> {
  try {
    const toolDescription = await toolDescriptor.describeTool(toolInput);
    console.log("Tool Description:", toolDescription);
    const tasks = await taskGenerator.generateTasks(toolDescription);
    console.log("Generated Tasks:", tasks);
  } catch (error) {
    console.error("Error describing tool:", error);
  }
}

export async function integrateDeliverables(deliverables: any[]): Promise<any> {
  try {
    const integratedDeliverable = await deliverableIntegrator.integrate(deliverables);
    console.log("Integrated Deliverable:", integratedDeliverable);
    return integratedDeliverable;
  } catch (error) {
    console.error("Error integrating deliverables:", error);
    throw error; // Propagate the error to the caller
  }
}

// Example usage
const toolInput = "A tool to automate the generation of project documentation.";
describeTool(toolInput);

const engineerDeliverables = [/* Array of deliverables from engineers */];
const integratedResult = await integrateDeliverables(engineerDeliverables);
console.log("Final Integrated Result:", integratedResult);
```

In this code snippet, we first import the tool classes from a hypothetical `tools.js` file. We then create instances of each tool: `toolDescriptor`, `taskGenerator`, and `deliverableIntegrator`.

The `describeTool` function takes a `toolInput` as an argument, uses the `toolDescriptor` to generate a description, and then employs the `taskGenerator` to create tasks based on that description. Any errors encountered during this process are caught and logged.

The `integrateDeliverables` function accepts an array of `deliverables` and uses the `deliverableIntegrator` to integrate them into a final product. Again, errors are caught and logged, but also rethrown to allow the caller to handle the error as needed.

